package cn.huankan.collector;
import java.util.*;import java.net.URI;import java.math.BigInteger;import java.nio.charset.StandardCharsets;
import com.fasterxml.jackson.databind.*;import cn.huankan.evidence.EvidenceService;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;
@Service public class GleifService {
 private final JdbcTemplate db;private final ObjectMapper json;private final OfficialHttpClient http;private final CollectorGuard guard;private final TransactionTemplate transaction;
 public GleifService(JdbcTemplate d,ObjectMapper j,OfficialHttpClient h,CollectorGuard g,PlatformTransactionManager t){db=d;json=j;http=h;guard=g;transaction=new TransactionTemplate(t);}
 public static boolean validLei(String lei){if(lei==null||!lei.matches("[A-Z0-9]{18}[0-9]{2}"))return false;StringBuilder numeric=new StringBuilder();for(char c:lei.toCharArray())numeric.append(c>='A'?(int)c-55:c-'0');return new BigInteger(numeric.toString()).mod(BigInteger.valueOf(97)).intValue()==1;}
 private String encoded(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalArgumentException("法人数据编码失败");}}
 public Object search(String name){if(name==null||name.isBlank()||name.length()>150)throw new IllegalArgumentException("法人搜索名称无效");approved();URI uri=URI.create("https://api.gleif.org/api/v1/lei-records?page%5Bsize%5D=10&filter%5Bentity.legalName%5D="+java.net.URLEncoder.encode(name,StandardCharsets.UTF_8));var r=http.get(uri,"HUANKAN local legal identity research",Map.of());if(r.status()!=200)throw new IllegalStateException("GLEIF_HTTP_"+r.status());try{return Map.of("candidates",json.readTree(r.body()).path("data"),"verification","名称检索候选，必须检查LEI与法人完整字段；未自动合并");}catch(Exception e){throw new IllegalArgumentException("GLEIF搜索响应异常");}}
 private void approved(){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM source_license WHERE source_id='GLEIF' AND status='APPROVED' AND access_allowed AND storage_allowed AND display_allowed AND (valid_until IS NULL OR valid_until>now()))",Boolean.class)))throw new IllegalStateException("GLEIF许可尚未确认");}
 public Object collect(String lei){if(!validLei(lei))throw new IllegalArgumentException("LEI格式或校验位不正确");approved();UUID job=UUID.randomUUID();try(var lease=guard.acquire("GLEIF")){if(lease==null)throw new IllegalStateException("GLEIF任务正在运行");db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'GLEIF','RUNNING')",job);int inserted=0;var root=fetch(job,lei,"");if(root==null)throw new IllegalStateException("GLEIF未返回法人记录");JsonNode record=root.path("data");if(!lei.equals(record.path("id").asText())||!lei.equals(record.path("attributes").path("lei").asText()))throw new IllegalArgumentException("GLEIF LEI绑定不一致");var a=record.path("attributes");if(a.path("entity").path("legalName").path("name").asText().isBlank())throw new IllegalArgumentException("GLEIF缺少正式名称");inserted+=transaction.execute(s->saveLegal(job,lei,a));
  var types=new LinkedHashMap<String,String>();types.put("direct","DIRECT");types.put("ultimate","ULTIMATE");for(var type:types.entrySet()){var links=record.path("relationships").path(type.getKey()+"-parent").path("links");boolean exception=links.has("reporting-exception");boolean relationship=links.has("relationship-record")||links.has("relationship-records");if(!exception&&!relationship)continue;String suffix="/"+type.getKey()+"-parent-"+(exception?"reporting-exception":"relationship");var data=fetch(job,lei,suffix);if(data==null)continue;String kind=type.getValue()+(exception?"_REPORTING_EXCEPTION":"_ACCOUNTING_PARENT");inserted+=transaction.execute(s->saveLevel2(job,lei,suffix,kind,data));}
  db.update("UPDATE ingestion_job SET status='SUCCESS',finished_at=clock_timestamp(),new_count=?,fetched_count=(SELECT count(*) FROM gleif_request WHERE job_id=?),duplicate_count=(SELECT count(*) FROM gleif_request WHERE job_id=?)-?,http_status=200 WHERE id=?",inserted,job,job,inserted,job);return Map.of("job_id",job,"stored_versions",inserted,"identity_scope","GLEIF法人登记字段；不推断证券、客户供应商或持股比例");
 }catch(Exception e){org.slf4j.LoggerFactory.getLogger(GleifService.class).warn("GLEIF任务 {} 保存失败",job,e);db.update("UPDATE ingestion_job SET status='FAILED',finished_at=clock_timestamp(),error_code=?,error_detail='GLEIF采集失败，保留原有法人和证据' WHERE id=?",e instanceof org.springframework.dao.DataAccessException?"DATABASE_CONSTRAINT_FAILURE":CollectorGuard.failure(e),job);throw new IllegalStateException("GLEIF采集失败："+(e instanceof org.springframework.dao.DataAccessException?"DATABASE_CONSTRAINT_FAILURE":CollectorGuard.failure(e)),e);}}
 private JsonNode fetch(UUID job,String lei,String suffix)throws Exception{String url="https://api.gleif.org/api/v1/lei-records/"+lei+suffix;var r=http.get(URI.create(url),"HUANKAN local legal identity research",Map.of());db.update("INSERT INTO gleif_request(id,job_id,url,status,raw_response,sha256,error) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID(),job,url,r.status(),r.body(),EvidenceService.hash(r.body()),r.status()==200?null:"HTTP_"+r.status());if(r.status()!=200)throw new IllegalStateException("HTTP_"+r.status());var data=json.readTree(r.body());if(data.path("data").isNull()||data.path("data").isMissingNode())throw new IllegalArgumentException("GLEIF空记录不能生成法人");return data;}
 private UUID proof(UUID job,String document){var response=db.queryForMap("SELECT * FROM gleif_request WHERE job_id=? AND url=? ORDER BY acquired_at DESC LIMIT 1",job,"https://api.gleif.org/api/v1/lei-records/"+document);byte[] raw=(byte[])response.get("raw_response");String hash=response.get("sha256").toString();var old=db.queryForList("SELECT id,revision,raw_content_hash,first_seen_at FROM raw_evidence WHERE source_id='GLEIF' AND source_document_id=? ORDER BY revision DESC LIMIT 1",document);if(!old.isEmpty()&&hash.equals(old.getFirst().get("raw_content_hash")))return null;UUID id=UUID.randomUUID();int version=old.isEmpty()?1:((Number)old.getFirst().get("revision")).intValue()+1;db.update("INSERT INTO raw_evidence(id,source_id,source_document_id,source_url,missing_time_reason,first_seen_at,raw_content,raw_content_hash,item_fingerprint,content_language,parser_version,revision,verification_status,job_id,collected_at,ingestion_kind) VALUES(?,'GLEIF',?,?,'登记更新时间不等同新闻发布时间',?,?,?,?,?,'GLEIF-JSON-1.0',?,'PENDING',?,?,?)",id,document,response.get("url"),old.isEmpty()?response.get("acquired_at"):old.getFirst().get("first_seen_at"),raw,hash,hash,"und",version,job,response.get("acquired_at"),version==1?"HISTORICAL_BACKFILL":"REVISION");db.update("INSERT INTO evidence_version VALUES(?,?,?)",id,old.isEmpty()?null:old.getFirst().get("id"),version==1?"INITIAL":"METADATA_CHANGED");db.update("UPDATE ingestion_job SET new_count=new_count+1 WHERE id=?",job);return id;}
 private int saveLegal(UUID job,String lei,JsonNode a){UUID evidence=proof(job,lei);if(evidence==null)return 0;String name=a.path("entity").path("legalName").path("name").asText(),country=a.path("entity").path("legalAddress").path("country").asText(null);UUID entity=UUID.randomUUID();db.update("INSERT INTO financial_entity(id,type,official_name,identity_key,source_id,source_url,evidence_id,status) VALUES(?,'COMPANY',?,?,'GLEIF',?,?, 'VERIFIED') ON CONFLICT(type,source_id,identity_key) DO NOTHING",entity,name,"LEI:"+lei,"https://api.gleif.org/api/v1/lei-records/"+lei,evidence);entity=db.queryForObject("SELECT id FROM financial_entity WHERE type='COMPANY' AND source_id='GLEIF' AND identity_key=?",UUID.class,"LEI:"+lei);db.update("INSERT INTO entity_identifier(entity_id,kind,value,evidence_id) VALUES(?,'LEI',?,?) ON CONFLICT DO NOTHING",entity,lei,evidence);
  String raw=db.queryForObject("SELECT convert_from(raw_content,'UTF8') FROM raw_evidence WHERE id=?",String.class,evidence);UUID profile=UUID.randomUUID();db.update("INSERT INTO entity_profile_version(id,entity_id,legal_name,original_name,country,official_identifier,evidence_id,excerpt) VALUES(?,?,?,?,?,?,?,?)",profile,entity,name,name,country,lei,evidence,raw);db.update("INSERT INTO entity_profile_review(profile_id,decision,reason,actor) VALUES(?,'VERIFIED','精确LEI校验位、官方JSON法人名称和司法辖区字段校验；仅登记身份范围','GLEIF字段校验-1.0')",profile);
  String last=a.path("registration").path("lastUpdateDate").asText(null);db.update("INSERT INTO gleif_legal_record VALUES(?,?,?,?,?,?::jsonb,?,?,?,?::jsonb)",evidence,entity,lei,name,a.path("entity").path("jurisdiction").asText(null),encoded(a.path("entity").path("legalAddress")),a.path("entity").path("status").asText(null),a.path("registration").path("status").asText(null),last==null?null:java.sql.Timestamp.from(java.time.Instant.parse(last)),encoded(a));return 1;}
 private int saveLevel2(UUID job,String lei,String suffix,String kind,JsonNode data){UUID evidence=proof(job,lei+suffix);if(evidence==null)return 0;String parent=data.path("data").path("attributes").path("relationship").path("endNode").path("id").asText(null);db.update("INSERT INTO gleif_level2 VALUES(?,?,?,?,?::jsonb,?)",evidence,lei,kind,parent,encoded(data.path("data")),kind.endsWith("EXCEPTION")?"母公司报告例外不证明不存在控制关系":"会计并表范围，不等于股权比例或真实供应链；需双方LEI核验");return 1;}
 public Object status(){return Map.of("records",db.queryForObject("SELECT count(*) FROM gleif_legal_record",Long.class),"level2",db.queryForObject("SELECT count(*) FROM gleif_level2",Long.class),"requests",db.queryForList("SELECT url,status,sha256,error,acquired_at FROM gleif_request ORDER BY acquired_at DESC LIMIT 50"),"rate_policy","沿用持久化域名预算，最多2次/秒及120次/分钟；官方数值上限尚未确认，不声称无限制");}
 @org.springframework.transaction.annotation.Transactional public Object linkRelations(){int inserted=0;var rows=db.queryForList("SELECT g.*,r.raw_content,r.raw_content_hash,r.source_url,c.entity_id child_id,p.entity_id parent_id FROM gleif_level2 g JOIN raw_evidence r ON r.id=g.evidence_id JOIN entity_identifier c ON c.kind='LEI' AND c.value=g.child_lei JOIN entity_identifier p ON p.kind='LEI' AND p.value=g.parent_lei WHERE g.kind IN('DIRECT_ACCOUNTING_PARENT','ULTIMATE_ACCOUNTING_PARENT') ORDER BY r.collected_at LIMIT 100");for(var row:rows){if(!EvidenceService.hash((byte[])row.get("raw_content")).equals(row.get("raw_content_hash")))throw new IllegalArgumentException("会计并表证据哈希异常");JsonNode data;try{data=json.readTree(row.get("details").toString());}catch(Exception e){throw new IllegalArgumentException("会计并表原始结构异常");}JsonNode a=data.path("attributes"),relation=a.path("relationship");String type="DIRECT_ACCOUNTING_PARENT".equals(row.get("kind"))?"ACCOUNTING_DIRECT_PARENT":"ACCOUNTING_ULTIMATE_PARENT",expected=type.equals("ACCOUNTING_DIRECT_PARENT")?"IS_DIRECTLY_CONSOLIDATED_BY":"IS_ULTIMATELY_CONSOLIDATED_BY";if(!expected.equals(relation.path("type").asText())||!row.get("child_lei").toString().equals(relation.path("startNode").path("id").asText())||!row.get("parent_lei").toString().equals(relation.path("endNode").path("id").asText()))throw new IllegalArgumentException("并表类型或双方LEI与官方JSON不一致");java.sql.Timestamp effective=null;for(var period:relation.path("periods"))if("RELATIONSHIP_PERIOD".equals(period.path("type").asText())&&period.hasNonNull("startDate"))effective=java.sql.Timestamp.from(java.time.Instant.parse(period.path("startDate").asText()));UUID id=UUID.randomUUID();String limitation="GLEIF官方登记会计并表关系；证据级别 "+a.path("registration").path("corroborationLevel").asText("未知")+"。首次公开时间未知，保持待审核；登记更新时间、记录有效期与关系期间分别保留。不证明证券、股权比例、客户或供应商关系";int count=db.update("INSERT INTO entity_relation(id,subject_id,object_id,type,evidence_id,explanation,effective_from,relation_kind) VALUES(?,?,?,?,?,?,?,'ACCOUNTING_CONSOLIDATION') ON CONFLICT DO NOTHING",id,row.get("child_id"),row.get("parent_id"),type,row.get("evidence_id"),limitation,effective);if(count>0){db.update("INSERT INTO relation_support(relation_id,evidence_id,excerpt,source_url) VALUES(?,?,?,?)",id,row.get("evidence_id"),new String((byte[])row.get("raw_content"),StandardCharsets.UTF_8),row.get("source_url"));inserted++;}}return Map.of("linked_pending",inserted,"verification","官方登记关系候选，公开时刻与独立核实仍不足");}
}
